// Lista de feeds RSS lidos a cada 15 minutos. Para acrescentar fontes sem editar o
// fluxo, use a variável ZENTRADE_FEEDS_RSS (URLs https separadas por vírgula).
const PADRAO = [
  { nome: 'Cointelegraph', url: 'https://cointelegraph.com/rss' },
  { nome: 'Decrypt', url: 'https://decrypt.co/feed' },
];

const extras = String($('Configuração').first().json.feedsExtras || '')
  .split(/[\s,]+/)
  .filter((url) => /^https:\/\/[^\s/?#]+\.[^\s]*$/.test(url))
  .map((url) => ({ nome: url.replace(/^https:\/\/(www\.)?/, '').split(/[/?#:]/)[0], url }));

const vistas = new Set();
return [...PADRAO, ...extras]
  .filter((f) => !vistas.has(f.url) && vistas.add(f.url))
  .map((f) => ({ json: f }));

// Junta anúncios da Binance e itens dos feeds RSS, descarta o que é velho ou já foi
// enviado e monta um resumo CURTO com link. Nunca envia a matéria inteira.
const JANELA_MS = 48 * 60 * 60 * 1000;
const FUTURO_TOLERADO_MS = 60 * 60 * 1000;
const MAXIMO_POR_RODADA = 30;
const RESUMO_MAX = 280;
const TITULO_MAX = 200;

const agora = Date.now();
const enviados = $getWorkflowStaticData('global').noticiasEnviadas || {};

const limpar = (s) =>
  String(s ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
const cortar = (s, max) => (s.length <= max ? s : `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`);
const hostDe = (url) => url.replace(/^https?:\/\/(www\.)?/, '').split(/[/?#:]/)[0];

const candidatos = [];

for (const item of $('Anúncios da Binance').all()) {
  const catalogos = item.json && item.json.data && Array.isArray(item.json.data.catalogs) ? item.json.data.catalogs : [];
  for (const catalogo of catalogos) {
    for (const artigo of Array.isArray(catalogo.articles) ? catalogo.articles : []) {
      if (typeof artigo.code !== 'string' || !/^[0-9a-f]{32}$/.test(artigo.code)) continue;
      const titulo = cortar(limpar(artigo.title), TITULO_MAX);
      if (!titulo) continue;
      const url = `https://www.binance.com/pt-BR/support/announcement/detail/${artigo.code}`;
      candidatos.push({
        titulo: `Binance: ${titulo}`.slice(0, TITULO_MAX),
        url,
        publicadoEm: Number(artigo.releaseDate),
        texto: `Anúncio oficial da Binance (${limpar(catalogo.catalogName) || 'anúncios'}): ${titulo}. Detalhes em ${url}`,
      });
    }
  }
}

for (const item of $input.all()) {
  const n = item.json || {};
  if (n.error || typeof n.link !== 'string' || !/^https?:\/\//.test(n.link)) continue;
  const titulo = cortar(limpar(n.title), TITULO_MAX);
  if (!titulo) continue;
  const resumo = cortar(limpar(n.contentSnippet || n.summary || n.content || ''), RESUMO_MAX);
  candidatos.push({
    titulo,
    url: n.link,
    publicadoEm: Date.parse(n.isoDate || n.pubDate || ''),
    texto: `${resumo || titulo}\n\nResumo curto de ${hostDe(n.link)}. Matéria completa: ${n.link}`,
  });
}

const vistos = new Set();
const carimbo = Math.floor(agora / 1000);
return candidatos
  .filter((c) => Number.isFinite(c.publicadoEm))
  .filter((c) => agora - c.publicadoEm <= JANELA_MS && c.publicadoEm - agora <= FUTURO_TOLERADO_MS)
  .filter((c) => enviados[c.url] === undefined && !vistos.has(c.url) && vistos.add(c.url))
  .sort((a, b) => b.publicadoEm - a.publicadoEm)
  .slice(0, MAXIMO_POR_RODADA)
  .map((c) => {
    const corpo = JSON.stringify({
      fonte: 'noticia',
      titulo: c.titulo,
      url: c.url,
      publicadoEm: Math.trunc(c.publicadoEm),
      texto: c.texto,
    });
    return { json: { chave: c.url, corpo, carimbo, mensagem: `${carimbo}.${corpo}` } };
  });

// Lembra o que a API aceitou, para não reenviar nas próximas rodadas. O que falhou
// fica de fora e é tentado de novo em 15 minutos.
const ESQUECER_APOS_MS = 7 * 24 * 60 * 60 * 1000;

const agora = Date.now();
const estado = $getWorkflowStaticData('global');
const enviados = { ...(estado.noticiasEnviadas || {}) };
const pedidos = $('Resumir e filtrar').all();

let aceitas = 0;
let falhas = 0;
$input.all().forEach((resposta, i) => {
  const chave = pedidos[i] && pedidos[i].json.chave;
  if (!chave) return;
  if (resposta.json && resposta.json.error) {
    falhas++;
    return;
  }
  enviados[chave] = agora;
  aceitas++;
});
for (const [chave, em] of Object.entries(enviados)) {
  if (agora - em > ESQUECER_APOS_MS) delete enviados[chave];
}
estado.noticiasEnviadas = enviados;

return [{ json: { aceitas, falhas } }];
